INSERT INTO spells (spell_name, level, casting_time, range, components, duration, concentration, description)
VALUES
    ('Fire Bolt', 0, 'ACTION', 120, 'V, S', 'Instantaneous', false, 'You hurl a mote of fire at a creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 fire damage. A flammable object hit by this spell ignites if it isn''t being worn or carried.'),
    ('Mage Hand', 0, 'ACTION', 30, 'V, S', '1 minute', false, 'A spectral, floating hand appears at a point you choose within range. The hand lasts for the duration or until you dismiss it as an action. The hand vanishes if it is ever more than 30 feet away from you or if you cast this spell again. You can use your action to control the hand. You can use the hand to manipulate an object, open an unlocked door or container, stow or retrieve an item from an open container, or pour the contents out of a vial. You can move the hand up to 30 feet each time you use it. The hand can''t attack, activate magical items, or carry more than 10 pounds.'),
    ('Prestidigitation', 0, 'ACTION', 10, 'V, S', 'Up to 1 hour', false, 'This spell is a minor magical trick that novice spellcasters use for practice. You create one of the following magical effects within range: you create an instantaneous, harmless sensory effect, such as a shower of sparks, a puff of wind, faint musical notes, or an odd odor; you instantaneously light or snuff out a candle, a torch, or a small campfire; you instantaneously clean or soil an object no larger than 1 cubic foot; you chill, warm, or flavor up to 1 cubic foot of nonliving material for 1 hour; you make a color, a small mark, or a symbol appear on an object or a surface for 1 hour; or you create a nonmagical trinket or an illusory image that can fit in your hand and that lasts until the end of your next turn. If you cast this spell multiple times, you can have up to three of its non-instantaneous effects active at a time, and you can dismiss such an effect as an action.'),
    ('Sacred Flame', 0, 'ACTION', 60, 'V, S', 'Instantaneous', false, 'Flame-like radiance descends on a creature that you can see within range. The target must succeed on a Dexterity saving throw or take 1d8 radiant damage. The target gains no benefit from cover for this saving throw. The spell''s damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).'),
    ('Guidance', 0, 'ACTION', 0, 'V, S', 'Concentration, up to 1 minute', true, 'You touch one willing creature. Once before the spell ends, the target can roll a d4 and add the number rolled to one ability check of its choice. It can roll the die before or after making the ability check. The spell then ends.'),
    ('Toll the Dead', 0, 'ACTION', 60, 'V, S', 'Instantaneous', false, 'You point at one creature you can see within range, and the sound of a dolorous bell fills the air around it for a moment. The target must succeed on a Wisdom saving throw or take 1d8 necrotic damage. If the target is missing any of its hit points, it instead takes 1d12 necrotic damage. The spell''s damage increases by one die when you reach 5th level (2d8 or 2d12), 11th level (3d8 or 3d12), and 17th level (4d8 or 4d12).'),
    ('Vicious Mockery', 0, 'ACTION', 60, 'V', 'Instantaneous', false, 'You unleash a string of insults laced with subtle enchantments at a creature you can see within range. If the target can hear you (though it need not understand you), it must succeed on a Wisdom saving throw or take 1d4 psychic damage and have disadvantage on the next attack roll it makes before the end of its next turn. This spell''s damage increases by 1d4 when you reach 5th level (2d4), 11th level (3d4), and 17th level (4d4).'),
    ('Shillelagh', 0, 'BONUS_ACTION', 0, 'V, S, M', '1 minute', false, 'The wood of a club or quarterstaff you are holding is imbued with nature''s power. For the duration, you can use your spellcasting ability instead of Strength for the attack and damage rolls of melee attacks using that weapon, and the weapon''s damage die becomes a d8. The weapon also becomes magical, if it isn''t already. The spell ends if you cast it again or if you let go of the weapon.'),
    ('Eldritch Blast', 0, 'ACTION', 120, 'V, S', 'Instantaneous', false, 'A beam of crackling energy streaks toward a creature within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 force damage. The spell creates more than one beam when you reach higher levels: two beams at 5th level, three beams at 11th level, and four beams at 17th level. You can direct the beams at the same target or at different ones. Make a separate attack roll for each beam.'),
    ('Thunderclap', 0, 'ACTION', 5, 'S', 'Instantaneous', false, 'You create a burst of thunderous sound that can be heard up to 100 feet away. Each creature within range, other than you, must succeed on a Constitution saving throw or take 1d6 thunder damage. The spell''s damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6).'),
